import base64, os, sys, subprocess

DOWNLOADS = os.path.join(os.environ.get("USERPROFILE",""), "Downloads")
for name in ["install_null_v3.py", "install_null_v3 (1).py", "install_null_v3 (2).py"]:
    p = os.path.join(DOWNLOADS, name)
    if os.path.exists(p): os.remove(p)

WORK_DIR = r"C:\Users\Mike\uap_sniffer\uap_sniffer"
ENCODED = ""
out = os.path.join(WORK_DIR, "null_distribution.py")
with open(out, "wb") as f:
    f.write(base64.b64decode(ENCODED))

with open(out, encoding="utf-8") as f:
    c = f.read()
assert "INTERMAGNET HAPI" in c, "Wrong file"
print(f"Wrote and verified: {out}")
subprocess.run([sys.executable, out], cwd=WORK_DIR)
